-- Script: 049-ajustes-inventario.sql
-- Módulo: 29 - AjustesInventario
-- Responsable: Maxi

CREATE TABLE "AjustesInventario" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "Codigo" character varying(20) NOT NULL,
    "AlmacenId" integer NOT NULL,
    "ProductoId" integer NOT NULL,
    "Tipo" character varying(15) NOT NULL,
    "Motivo" character varying(30) NOT NULL,
    "Cantidad" integer NOT NULL,
    "CostoUnitario" numeric(18,4) NOT NULL,
    "Fecha" timestamp with time zone NOT NULL,
    "Responsable" character varying(100) NOT NULL,
    "Observaciones" character varying(500),
    CONSTRAINT "PK_AjustesInventario" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_AjustesInventario_Almacenes_AlmacenId" FOREIGN KEY ("AlmacenId") REFERENCES "Almacenes" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_AjustesInventario_Productos_ProductoId" FOREIGN KEY ("ProductoId") REFERENCES "Productos" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_AjustesInventario_Tipo" CHECK ("Tipo" IN ('Incremento', 'Decremento')),
    CONSTRAINT "CK_AjustesInventario_Motivo" CHECK ("Motivo" IN ('ConteoFisico', 'Merma', 'Dano', 'Caducidad', 'Correccion')),
    CONSTRAINT "CK_AjustesInventario_Cantidad" CHECK ("Cantidad" BETWEEN 1 AND 1000000),
    CONSTRAINT "CK_AjustesInventario_Costo" CHECK ("CostoUnitario" > 0)
);

CREATE UNIQUE INDEX "IX_AjustesInventario_Codigo" ON "AjustesInventario" ("Codigo");
CREATE UNIQUE INDEX "IX_AjustesInventario_Codigo_Normalizado" ON "AjustesInventario" (lower(btrim("Codigo")));
CREATE INDEX "IX_AjustesInventario_AlmacenId" ON "AjustesInventario" ("AlmacenId");
CREATE INDEX "IX_AjustesInventario_ProductoId" ON "AjustesInventario" ("ProductoId");
CREATE INDEX "IX_AjustesInventario_Fecha" ON "AjustesInventario" ("Fecha");

ALTER TABLE "MovimientosKardex" ADD COLUMN "AjusteInventarioId" integer;
ALTER TABLE "MovimientosKardex" ADD CONSTRAINT "FK_MovimientosKardex_AjustesInventario_AjusteInventarioId" FOREIGN KEY ("AjusteInventarioId") REFERENCES "AjustesInventario" ("Id") ON DELETE RESTRICT;
CREATE INDEX "IX_MovimientosKardex_AjusteInventarioId" ON "MovimientosKardex" ("AjusteInventarioId");
